atomic_distribute_rake.definition:
CREATE OR REPLACE FUNCTION public.atomic_distribute_rake(p_table_id uuid, p_club_id uuid, p_hand_id uuid, p_hand_number integer, p_rake numeric, p_bbj numeric DEFAULT 0, p_pot numeric DEFAULT NULL::numeric, p_num_players integer DEFAULT (NULL::numeric)::integer, p_contributions jsonb DEFAULT NULL::jsonb, p_tournament_id uuid DEFAULT NULL::uuid, p_returned_uncalled jsonb DEFAULT NULL::jsonb, p_rake_method text DEFAULT 'DEALT_EQUAL'::text)
 RETURNS TABLE(applied boolean, already_processed boolean, recovered boolean, rake_record_id uuid, club_net_credit numeric, spendable_route text, spendable_amount numeric, union_id_out uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '30s'
AS $function$
DECLARE
  v_bank_receipt_id uuid; v_banked_at timestamptz;
  v_union_id     uuid;
  v_g_union      uuid;
  v_is_private   boolean := false;
  v_club_name    text;
  v_net          numeric;
  v_bbj          numeric := COALESCE(p_bbj, 0);
  v_rr_id        uuid;
  v_first_claim  boolean := false;
  v_recovered    boolean := false;
  v_leg_key      uuid;
  v_n            integer;
  v_cw_after     numeric;
  v_union_rake   numeric;
  v_route        text;
  v_method       text;
  v_alloc_sum    numeric;
  v_st           text;
  v_msg          text;
  v_dup_id       uuid;
BEGIN
  IF p_club_id IS NULL OR p_rake IS NULL OR p_rake <= 0 THEN
    RETURN QUERY SELECT false, false, false, NULL::uuid, 0::numeric,
                        NULL::text, 0::numeric, NULL::uuid;
    RETURN;
  END IF;

  /* ZERO-DRIFT (2026-08-31): declare the ledger context for this transaction
     so every auto-journaled balance delta below is categorized as rake coming
     off the felt, not an anonymous adjustment against suspense. */
  PERFORM set_config('app.ledger_category', 'rake', true);
  PERFORM set_config('app.ledger_counterparty', 'table_stack', true);
  PERFORM set_config('app.ledger_counterparty_entity', COALESCE(p_table_id::text, ''), true);
  -- PHASE 6.4 (2026-09-05): the rake's legs name the hand when it is known.
  PERFORM set_config('app.ledger_hand_id', COALESCE(p_hand_id::text, ''), true);
  /* THE RAKE LEG NAMES THE CLUB IT WAS EARNED IN (2026-09-21). Union rake
     is routed by UPDATE-ing union_wallets.rake_wallet; the fn_ca_autoledger
     trigger journals that delta, and union_wallets has no club_id column,
     so every union rake leg was written club-less - 294,877 rows and
     671514.09 in the week of 2026-09-07 alone, and still happening.
     20260920192513 taught the autoledger to read a declaring payer and
     fixed the PRIZE legs; this is the rake payer saying the same thing.
     NOT app.ledger_club_id: that name decides which club a WALLET credit
     is paid into (atomic_credit_wallet_and_log) and is set and restored by
     the rakeback close, so clearing it here would move money. */
  PERFORM set_config('app.ledger_autoledger_club_id', COALESCE(p_club_id::text, ''), true);

  v_method := CASE WHEN p_rake_method = 'WEIGHTED_CONTRIBUTED'
                   THEN 'WEIGHTED_CONTRIBUTED' ELSE 'DEALT_EQUAL' END;

  v_net := p_rake - v_bbj;

  SELECT c.name INTO v_club_name FROM public.clubs c WHERE c.id = p_club_id;

  -- UNION LAW (Dan, restored 2026-08-30): route by the GAME's union stamp,
  -- not club membership. A private club game's rake NEVER touches the union.
  IF p_table_id IS NOT NULL THEN
    SELECT COALESCE(t.is_private, false), t.union_id
      INTO v_is_private, v_g_union
      FROM public.tables t WHERE t.id = p_table_id;
  END IF;
  IF p_tournament_id IS NOT NULL AND NOT v_is_private AND v_g_union IS NULL THEN
    SELECT COALESCE(tr.is_private, false), tr.union_id
      INTO v_is_private, v_g_union
      FROM public.tournaments tr WHERE tr.id = p_tournament_id;
  END IF;

  IF v_is_private THEN
    v_union_id := NULL;
  ELSE
    v_union_id := v_g_union;
  END IF;

  /* A HAND THAT CANNOT NAME ITSELF BY ID STILL NAMES ITSELF BY TABLE AND
     NUMBER (2026-09-06). Both idempotency guards below key on p_hand_id, and
     both are disabled when it is NULL: ON CONFLICT (hand_id) WHERE hand_id IS
     NOT NULL matches nothing, and v_leg_key fell back to a FRESH RANDOM uuid,
     so rake_distribution_legs could not dedupe either. The engine calls this
     before logHandHistory has produced a hand row and again after, and the
     second call was treated as a new hand: a duplicate rake_records row, and
     a second increment of the club wallet's period and lifetime rake. 4,452
     such rows exist, 2026-04-16 to 2026-09-05, carrying 16,426.46 of rake and
     2,068.82 of BBJ contribution that no hand ever dropped - measured against
     hand_history and bbj_contributions, which agree with the LINKED rows alone
     in 283 of the 284 cases where the hand still exists.

     So: ask hand_history for the id first, and if it genuinely is not there
     yet, key on what the caller always knows - the table and the hand number. */
  IF p_hand_id IS NULL AND p_table_id IS NOT NULL AND p_hand_number IS NOT NULL THEN
    SELECT h.id INTO p_hand_id
      FROM public.hand_history h
     WHERE h.table_id = p_table_id
       AND h.hand_number = p_hand_number
     ORDER BY h.created_at DESC
     LIMIT 1;
    -- Phase 6.4: the legs name the hand as soon as we know it.
    PERFORM set_config('app.ledger_hand_id', COALESCE(p_hand_id::text, ''), true);
  END IF;

  IF p_hand_id IS NULL AND p_table_id IS NOT NULL AND p_hand_number IS NOT NULL THEN
    SELECT rr.id INTO v_dup_id
      FROM public.rake_records rr
     WHERE rr.table_id = p_table_id
       AND rr.hand_id IS NULL
       AND (rr.metadata->>'hand_number') = p_hand_number::text
       AND rr.created_at > now() - interval '2 days'
     ORDER BY rr.created_at
     LIMIT 1;
    IF v_dup_id IS NOT NULL THEN
      PERFORM set_config('app.ledger_autoledger_club_id', '', true);
      RETURN QUERY SELECT false, true, false, v_dup_id, 0::numeric,
                          NULL::text, 0::numeric, v_union_id;
      RETURN;
    END IF;
  END IF;

  IF p_hand_id IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('accounting_cash_hand:'||p_hand_id::text,0));
  END IF;
  PERFORM public.fn_lock_cash_bank_accounting_week(p_club_id,v_union_id,transaction_timestamp());

  INSERT INTO public.rake_records (
    hand_id, table_id, club_id, rake_amount, bbj_contribution, pot_size,
    num_players, player_contributions, is_tournament, tournament_id, source,
    metadata, rake_method, returned_uncalled
  ) VALUES (
    p_hand_id, p_table_id, p_club_id, p_rake, v_bbj, p_pot,
    p_num_players, p_contributions, (p_tournament_id IS NOT NULL), p_tournament_id,
    'atomic_distribute_rake',
    jsonb_build_object('hand_number', p_hand_number, 'is_private', v_is_private, 'union_id', v_union_id, 'accounting_source_version', 2),
    v_method, p_returned_uncalled
  )
  ON CONFLICT (hand_id) WHERE hand_id IS NOT NULL DO NOTHING
  RETURNING id INTO v_rr_id;

  IF v_rr_id IS NOT NULL THEN
    v_first_claim := true;
  ELSE
    SELECT id INTO v_rr_id FROM public.rake_records
      WHERE hand_id = p_hand_id ORDER BY created_at LIMIT 1;
  END IF;

  IF v_first_claim AND p_hand_id IS NOT NULL
     AND p_contributions IS NOT NULL AND jsonb_typeof(p_contributions) = 'object' THEN
    INSERT INTO public.rake_attributions (
      hand_id, player_id, rake_amount, rake_record_id, table_id, club_id,
      gross_contribution, returned_uncalled, eligible_contribution,
      contribution_weight, weighted_rake_credit, bbj_attributed_contribution,
      rake_method
    )
    SELECT p_hand_id,
           a.user_id,
           a.credit,
           v_rr_id, p_table_id,
           public.fn_cash_earning_club(p_hand_id,p_table_id,a.user_id,p_club_id,v_union_id),
           (p_contributions ->> a.user_id::text)::numeric
             + COALESCE((p_returned_uncalled ->> a.user_id::text)::numeric, 0),
           COALESCE((p_returned_uncalled ->> a.user_id::text)::numeric, 0),
           (p_contributions ->> a.user_id::text)::numeric,
           a.weight,
           a.credit,
           COALESCE(b.credit, 0),
           v_method
      FROM public.fn_allocate_rake_credits(p_rake, p_contributions, v_method) a
      LEFT JOIN public.fn_allocate_rake_credits(v_bbj, p_contributions, v_method) b
        ON b.user_id = a.user_id
    ON CONFLICT (hand_id, player_id) DO NOTHING;

    SELECT COALESCE(SUM(a.credit), 0) INTO v_alloc_sum
      FROM public.fn_allocate_rake_credits(p_rake, p_contributions, v_method) a;
    IF v_alloc_sum <> round(p_rake, 2) AND v_alloc_sum <> 0 THEN
      INSERT INTO public.financial_alerts (severity, source, message, context)
      VALUES ('critical', 'atomic_distribute_rake', 'RAKE_ALLOCATION_MISMATCH',
        jsonb_build_object('hand_id', p_hand_id, 'rake', p_rake,
          'allocated', v_alloc_sum, 'method', v_method));
    END IF;
  END IF;

  /* THE LEG KEY IS DERIVED, NEVER RANDOM (2026-09-06). A random key made
     rake_distribution_legs' ON CONFLICT (leg_key, leg) unreachable, so the
     club wallet's period and lifetime rake were incremented again for a hand
     already counted. When the hand has no id, the key is the table and the
     hand number - the same hand always produces the same key. */
  v_leg_key := COALESCE(
    p_hand_id,
    CASE WHEN p_table_id IS NOT NULL AND p_hand_number IS NOT NULL
         THEN md5('rake:' || p_table_id::text || ':' || p_hand_number::text)::uuid
    END,
    gen_random_uuid());
  PERFORM set_config('app.ledger_settlement', 'rake:' || v_leg_key::text, true);

  INSERT INTO public.rake_distribution_legs (leg_key, leg, club_id, union_id, amount)
  VALUES (v_leg_key, 'club_accumulator', p_club_id, v_union_id, v_net)
  ON CONFLICT (leg_key, leg) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    /* A CLUB'S RAKE TOTAL IS NOT A LOCK ON ITS WALLET (2026-10-02). This used
       to be an UPDATE of the club's one club_wallets row, held to COMMIT by
       every raked hand of every table in the club, and by every tournament
       finish of the club (which takes the same row first). It was the
       statement behind 1,518 of the platform's statement timeouts between
       18:00 and 19:45 UTC on 2026-10-02 and the lease_proof_expired burst
       that voided 180 hands at 19:37. The running total is kept per TABLE:
       a table deals one hand at a time, so its row has one writer. The club
       figure is the wallet's own column (tournament rake and history) plus
       the sum of its tables (fn_club_money_panel). No chip moves here; the
       club share is paid weekly from the rake treasury (2026-09-02 ruling). */
    INSERT INTO public.club_table_rake_totals AS t
           (club_id, table_id, rake_collected, bbj_contribution, hands, updated_at)
    VALUES (p_club_id, COALESCE(p_table_id, '00000000-0000-0000-0000-000000000000'::uuid),
            p_rake, v_bbj, 1, now())
    ON CONFLICT (club_id, table_id) DO UPDATE
       SET rake_collected   = t.rake_collected   + EXCLUDED.rake_collected,
           bbj_contribution = t.bbj_contribution + EXCLUDED.bbj_contribution,
           hands            = t.hands + 1,
           updated_at       = now();

    -- The receipt shows the wallet as it stands. Reading it takes no lock.
    SELECT w.chip_balance INTO v_cw_after
      FROM public.club_wallets w WHERE w.club_id = p_club_id;
    IF NOT FOUND THEN
      INSERT INTO public.club_wallets (club_id, chip_balance) VALUES (p_club_id, 0)
      ON CONFLICT (club_id) DO NOTHING;
      SELECT w.chip_balance INTO v_cw_after
        FROM public.club_wallets w WHERE w.club_id = p_club_id;
    END IF;

    INSERT INTO public.club_wallet_transactions (
      club_id, type, amount, balance_after, related_id, reason
    ) VALUES (
      p_club_id, 'rake_in', v_net, v_cw_after, p_hand_id,
      'Rake collected (hand ' || COALESCE('#' || p_hand_number::text, 'unknown') ||
        ', BBJ contribution ' || v_bbj::text || ')'
    );

    IF NOT v_first_claim THEN v_recovered := true; END IF;
  END IF;

  IF v_union_id IS NOT NULL THEN
    v_route := 'union_rake_wallet';
    INSERT INTO public.rake_distribution_legs (leg_key, leg, club_id, union_id, amount)
    VALUES (v_leg_key, 'union_rake', p_club_id, v_union_id, p_rake)
    ON CONFLICT (leg_key, leg) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n > 0 THEN
      -- UNION LAW (restored 2026-08-30): RAKE TREASURY ONLY. chip_balance
      -- (Union Bank) is deliberately NOT touched.
      INSERT INTO public.union_wallets (union_id, chip_balance, rake_wallet, total_rake_collected)
           VALUES (v_union_id, 0, p_rake, p_rake)
      ON CONFLICT (union_id) DO UPDATE SET
           rake_wallet          = public.union_wallets.rake_wallet + p_rake,
           total_rake_collected = COALESCE(public.union_wallets.total_rake_collected, 0) + p_rake,
           updated_at           = NOW()
      RETURNING rake_wallet INTO v_union_rake;

      INSERT INTO public.union_wallet_transactions (
        union_id, club_id, amount, tx_type, wallet, direction, balance_after, notes
      ) VALUES (
        v_union_id, p_club_id, p_rake, 'rake', 'rake_wallet', 'credit', v_union_rake,
        'Cash game rake: hand #' || COALESCE(p_hand_number::text, '?') ||
          ' (' || COALESCE(v_club_name, 'club') || ')'
      ) RETURNING id,created_at INTO v_bank_receipt_id,v_banked_at;
      INSERT INTO public.accounting_cash_bank_receipts(rake_record_id,union_id,club_id,union_transaction_id,banked_at,amount)
       VALUES(v_rr_id,v_union_id,p_club_id,v_bank_receipt_id,v_banked_at,p_rake);

      IF NOT v_first_claim THEN v_recovered := true; END IF;
    END IF;
  ELSE
    v_route := 'chip_retirement';
    -- Retain the original leg key so an earlier treasury credit cannot be
    -- replayed as a second disposition. A historical treasury leg needs an
    -- explicit adjustment; it is not evidence that this source was burned.
    IF EXISTS(SELECT 1 FROM public.rake_distribution_legs
       WHERE leg_key=v_leg_key AND leg='chip_treasury')
     AND NOT EXISTS(SELECT 1 FROM public.accounting_cash_bank_receipts b
       JOIN public.chip_ledger l ON l.id=b.club_ledger_id
       WHERE b.rake_record_id=v_rr_id AND b.union_id IS NULL AND b.union_transaction_id IS NULL
        AND b.club_id=p_club_id AND b.amount=p_rake AND l.amount=b.amount AND l.created_at=b.banked_at
        AND l.from_type='table_stack' AND l.to_type='chip_retirement' AND l.to_entity_id IS NULL
        AND l.club_id=p_club_id AND l.category='burn') THEN
      RAISE EXCEPTION 'cash_rake_legacy_treasury_leg_requires_adjustment' USING ERRCODE='55000';
    END IF;
    INSERT INTO public.rake_distribution_legs (leg_key, leg, club_id, union_id, amount)
    VALUES (v_leg_key, 'chip_treasury', p_club_id, NULL, p_rake)
    ON CONFLICT (leg_key, leg) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    IF v_n > 0 THEN
      -- A LIFETIME TOTAL IS NOT A LOCK ON THE CLUB ROW (2026-09-29).
      -- This branch used to run, once per raked hand:
      --     UPDATE public.clubs SET total_rake = total_rake + p_rake
      -- public.clubs holds one row per club and carries fifteen UPDATE
      -- triggers, so a counter bump ran every lifecycle guard, the settings
      -- audit, the autoledger and four management event emitters, and then
      -- held an exclusive lock on that single row for the REST of the hand
      -- projection transaction: the whole stats projection,
      -- ca_hand_player_facts_one, and a PostgREST round trip before COMMIT.
      -- Measured on production 2026-09-29 03:34 to 03:40 UTC: public.clubs
      -- was the most contended tuple behind Lock/transactionid, at 123,272
      -- updates against 10 live rows and 95 percent dead tuples in 756 pages.
      -- Nothing reads the column. No SQL function selects clubs.total_rake
      -- and no page does either, and it had already drifted away from the
      -- wallet total it duplicates: Deep Stack Society 1,685,329.42 against
      -- 1,685,313.29, Club JAQK 1,557,737.60 against 1,509,880.89, and both
      -- SHARK CLUB and Midway Union sat at 0.00 while their wallets held
      -- 1,523,835.54 and 3,710,512.50, because the union route never wrote
      -- it at all. The rake is receipted by the rake_records row inserted
      -- above and totalled by club_wallets.lifetime_rake_collected, both in
      -- this same transaction, so no figure is lost by not writing a third.
      -- The existing deferred chip_ledger issuance trigger registers this
      -- retirement. Calling fn_ca_burn would debit a wallet a second time;
      -- the hand settlement already removed these chips from table stacks.
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, to_type, to_entity_id,
         amount, category, club_id, table_id, hand_id, tournament_id, description)
      VALUES (
        COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid),
        'table_stack', p_table_id, 'chip_retirement', NULL,
        p_rake, 'burn', p_club_id, p_table_id, p_hand_id, p_tournament_id,
        'Standalone cash rake retired, hand ' || COALESCE('#' || p_hand_number::text, 'unknown')
          || ' (atomic_distribute_rake)') RETURNING id,created_at INTO v_bank_receipt_id,v_banked_at;
      -- The existing immutable source/ledger join records disposition; this
      -- private leg is a burn receipt and must never be counted as funding.
      INSERT INTO public.accounting_cash_bank_receipts(rake_record_id,union_id,club_id,club_ledger_id,banked_at,amount)
       VALUES(v_rr_id,NULL,p_club_id,v_bank_receipt_id,v_banked_at,p_rake);
      -- Any journal or receipt failure aborts the same producer transaction.
      IF NOT v_first_claim THEN v_recovered := true; END IF;
    END IF;
  END IF;

  PERFORM set_config('app.ledger_autoledger_club_id', '', true);
  RETURN QUERY SELECT v_first_claim, (NOT v_first_claim), v_recovered, v_rr_id,
                      CASE WHEN v_union_id IS NULL THEN 0::numeric ELSE v_net END, v_route,
                      CASE WHEN v_union_id IS NULL THEN 0::numeric ELSE p_rake END, v_union_id;
END;
$function$

fn_ca_autoledger.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_autoledger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  spec text; col text; acct text;
  o jsonb; nn jsonb;
  d numeric; oldv numeric; newv numeric;
  cat text; cp text; cpid uuid; cplbl text;
  v_club uuid; v_union uuid; v_entity uuid; v_guc_club uuid;
  actor uuid;
  v_st text; v_msg text;
BEGIN
  IF current_setting('app.ledger_autoskip_' || TG_TABLE_NAME, true) = '1' THEN
    RETURN NEW;
  END IF;

  o  := CASE WHEN TG_OP = 'INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
  nn := to_jsonb(NEW);

  cat := COALESCE(NULLIF(current_setting('app.ledger_category', true), ''), 'adjustment');
  cp  := COALESCE(NULLIF(current_setting('app.ledger_counterparty', true), ''), 'settlement_suspense');
  BEGIN
    cpid := NULLIF(current_setting('app.ledger_counterparty_entity', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN cpid := NULL;
  END;
  /* THE COUNTERPARTY NAMES ITS COLUMN (2026-10-04). A union wallet holds six
     balances and a promo bank lives on three kinds of owner, so the side this
     trigger writes for a declared union_wallet or promo_wallet counterparty
     carries the column the caller declared on app.ledger_counterparty_label.
     A label that cannot belong to the declared counterparty is not written:
     a stale declaration never names the wrong account. */
  cplbl := NULLIF(current_setting('app.ledger_counterparty_label', true), '');
  cplbl := CASE
    WHEN cp = 'union_wallet' AND cplbl LIKE 'union_wallets.%' THEN cplbl
    WHEN cp = 'bbj_pool' AND cplbl = 'bbj_pools.main_balance' THEN cplbl
    WHEN cp = 'promo_wallet' AND cplbl IN ('clubs.promo_balance', 'agents.promo_wallet_balance',
                                           'union_wallets.promo_wallet') THEN cplbl
    ELSE NULL END;
  actor := COALESCE(auth.uid(), '2d1cd6c3-5700-4af9-a271-d4863fdab20d'::uuid);

  /* THE JOURNAL LEG NAMES THE CLUB THE MONEY LANDED IN (2026-09-20).
     union_wallets and unions are the only autoledgered tables with no
     club_id column - `nn ? 'club_id'` is key EXISTENCE, so a table
     that has the column takes the arm above even when it is NULL. Before
     today every leg journalled from those two was written club-less, and
     fn_chip_drift_since_baseline filters movements on club_id IS NOT
     NULL while counting the balance they explain, so correctly paid
     union-hosted prizes were reported as member drift.
     A payer that knows the club declares it on
     app.ledger_autoledger_club_id, transaction-scoped, and clears it
     beside the autoskips. It is deliberately NOT app.ledger_club_id:
     that name is taken and decides which club a WALLET credit is paid
     into (atomic_credit_wallet_and_log, atomic_deduct_wallet_and_log,
     log_wallet_transaction), so borrowing it would let a rakeback
     close's club leak onto a union leg and would move real money when
     cleared. Read through an exception guard exactly as cpid is above:
     a malformed value must never abort a chip movement. */
  BEGIN
    v_guc_club := NULLIF(current_setting('app.ledger_autoledger_club_id', true), '')::uuid;
  EXCEPTION WHEN OTHERS THEN v_guc_club := NULL;
  END;
  v_club := CASE
    WHEN TG_TABLE_NAME = 'clubs' THEN (nn->>'id')::uuid
    WHEN nn ? 'club_id' THEN NULLIF(nn->>'club_id','')::uuid
    ELSE v_guc_club END;
  v_union := CASE
    WHEN TG_TABLE_NAME = 'unions' THEN (nn->>'id')::uuid
    WHEN nn ? 'union_id' THEN NULLIF(nn->>'union_id','')::uuid
    ELSE NULL END;
  v_entity := CASE
    WHEN TG_TABLE_NAME = 'agents' THEN NULLIF(nn->>'user_id','')::uuid
    WHEN TG_TABLE_NAME = 'club_members' THEN NULLIF(nn->>'user_id','')::uuid
    ELSE COALESCE(NULLIF(nn->>'id','')::uuid, v_club, v_union) END;

  FOR i IN 0 .. TG_NARGS - 1 LOOP
    spec := TG_ARGV[i];
    col  := split_part(spec, '=', 1);
    acct := split_part(spec, '=', 2);
    oldv := COALESCE(NULLIF(o->>col,'')::numeric, 0);
    newv := COALESCE(NULLIF(nn->>col,'')::numeric, 0);
    d := round(newv - oldv, 2);
    CONTINUE WHEN d = 0;
    /* THE AUTOLEDGER NEVER JOURNALS AN ACCOUNT TO ITSELF (2026-10-15). A leg
       whose counterparty is this very account, unlabelled, is from and to the
       same account (2026-10-06 15:42 KF player to three club treasuries;
       2026-09-17 16:39/16:41 treasury to promo). It nets to zero in every
       tally, so it is not written. A bbj_pool, a union_wallet and a promo bank
       off a club hold more than one column under one key, and their bare
       self-legs are the only record of which column moved: kept. */
    CONTINUE WHEN cp = acct AND cpid IS NOT DISTINCT FROM v_entity AND cplbl IS NULL
              AND acct NOT IN ('bbj_pool', 'union_wallet')
              AND (acct <> 'promo_wallet' OR TG_TABLE_NAME = 'clubs');

    BEGIN
      INSERT INTO public.chip_ledger
        (performed_by, from_type, from_entity_id, from_label,
         to_type, to_entity_id, to_label,
         amount, category, club_id, union_id, description,
         pre_from_balance, post_from_balance, pre_to_balance, post_to_balance)
      VALUES (actor,
        CASE WHEN d > 0 THEN cp   ELSE acct END,
        CASE WHEN d > 0 THEN cpid ELSE v_entity END,
        CASE WHEN d > 0 THEN cplbl ELSE TG_TABLE_NAME || '.' || col END,
        CASE WHEN d > 0 THEN acct ELSE cp END,
        CASE WHEN d > 0 THEN v_entity ELSE cpid END,
        CASE WHEN d > 0 THEN TG_TABLE_NAME || '.' || col ELSE cplbl END,
        abs(d), cat, v_club, v_union,
        'auto-ledgered ' || TG_TABLE_NAME || '.' || col || ' delta ' || d::text,
        CASE WHEN d < 0 THEN oldv END, CASE WHEN d < 0 THEN newv END,
        CASE WHEN d > 0 THEN oldv END, CASE WHEN d > 0 THEN newv END);
    EXCEPTION WHEN OTHERS THEN
      -- A journal failure must abort the enclosing chip movement.
      -- Preserve SQLSTATE so the existing caller can retry the whole operation.
      RAISE;
    END;
  END LOOP;

  RETURN NEW;
END $function$

fn_ca_balance_has_its_ledger_row.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_balance_has_its_ledger_row()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_ver text := NULLIF(current_setting('ca.ledger_tally_ver', true), '');
  v_checked text := NULLIF(current_setting('ca.ledger_tally_checked', true), '');
  v_mode text;
  t jsonb;
  r record;
  v_b numeric; v_l numeric;
  v_s numeric; v_moved text; v_moved_abs numeric;
BEGIN
  /* Deferred to commit. Every queued event re-enters here, so the tally is
     verified once per version: when nothing has been added since the last
     verification this is one setting read and out. A deferred trigger that
     writes money after us bumps the version and queues its own event, which
     verifies again, so the last word is always on the complete tally. */
  IF v_ver IS NULL OR v_ver = v_checked THEN
    RETURN NULL;
  END IF;

  t := COALESCE(NULLIF(current_setting('ca.ledger_tally', true), '')::jsonb, '{}'::jsonb);

  FOR r IN SELECT key, value FROM jsonb_each(t) LOOP
    v_b := round(COALESCE((r.value ->> 'b')::numeric, 0), 2);
    v_l := round(COALESCE((r.value ->> 'l')::numeric, 0), 2);
    IF v_b = v_l THEN
      CONTINUE;
    END IF;

    /* 2026-10-02: each store is judged by its own mode
       (ca_ledger_invariant_store_mode, keyed by the account-key prefix), so a
       store still being measured records a finding while a proven store
       refuses. A store with no row falls back to the one global row. */
    v_mode := COALESCE(
      (SELECT sm.mode FROM public.ca_ledger_invariant_store_mode sm WHERE sm.store = split_part(r.key, ':', 1)),
      (SELECT m.mode FROM public.ca_ledger_invariant_mode m LIMIT 1),
      'refuse');

    IF v_mode = 'refuse' THEN
      /* 20261002135708: the refusal rolls this transaction back, so it is
         recorded first on the recorder's own connection, which commits on
         its own. The recorder never raises and never changes the refusal. */
      BEGIN
        PERFORM public.fn_ca_ledger_refusal_record(jsonb_build_object(
          'kind',          'balance_moved_without_its_ledger_row',
          'account_key',   r.key,
          'store',         split_part(r.key, ':', 1),
          'balance_delta', v_b,
          'ledger_net',    v_l,
          'mode',          v_mode,
          'first_writer',  left(COALESCE(r.value ->> 'q', '(unknown statement)'), 1000),
          'message',       format('REFUSED: balance_moved_without_its_ledger_row account=%s balance_delta=%s ledger_net=%s', r.key, v_b, v_l)));
      EXCEPTION WHEN OTHERS THEN
        NULL;
      END;
      RAISE EXCEPTION 'REFUSED: balance_moved_without_its_ledger_row account=% balance_delta=% ledger_net=%',
        r.key, v_b, v_l
        USING ERRCODE = '23514',
              DETAIL  = CASE
                          WHEN v_l = 0 THEN 'the balance column moved and no chip_ledger leg in this transaction accounts for it'
                          WHEN v_b = 0 THEN 'a chip_ledger leg names this account and its balance column did not move in this transaction'
                          ELSE 'the balance column and the chip_ledger legs in this transaction disagree on how much moved'
                        END || '; first written in this transaction by: ' || COALESCE(r.value ->> 'q', '(unknown statement)'),
              HINT    = 'Every chip movement is written by its door as balance + leg in one transaction. If the door stood the autoledger down (app.ledger_autoskip_<table>), its own leg must equal the delta and name the same user, club, union, pool, table, tournament or ticket float. Nothing is corrected here; the transaction is refused whole.';
    END IF;

    INSERT INTO public.ca_ledger_invariant_findings
      (txid, account_key, balance_delta, ledger_net, mode, actor_service, db_role, statement)
    VALUES
      (pg_current_xact_id(), r.key, v_b, v_l, v_mode,
       current_setting('application_name', true), current_user,
       COALESCE(r.value ->> 'q', left(current_query(), 300)))
    ON CONFLICT (txid, account_key) DO UPDATE
      SET balance_delta = EXCLUDED.balance_delta,
          ledger_net    = EXCLUDED.ledger_net,
          found_at      = EXCLUDED.found_at,
          statement     = EXCLUDED.statement;
    RAISE WARNING 'OBSERVED: balance_moved_without_its_ledger_row account=% balance_delta=% ledger_net=% (store mode observe; this transaction would be refused)',
      r.key, v_b, v_l;
  END LOOP;

  /* NO BALANCE MOVES AGAINST SETTLEMENT SUSPENSE (2026-10-02). Every store
     above can balance and the chips still come from nowhere: a journal
     trigger whose writer declared no counterparty posts the store's leg
     against settlement_suspense, which holds no balance and is outside the
     supply count. A transaction that wrote a suspense leg may not move any
     covered balance. A journal-only suspense correction moves none. */
  v_s := round(COALESCE((t -> 'settlement_suspense' ->> 's')::numeric, 0), 2);
  IF v_s <> 0 THEN
    SELECT string_agg(e.key || ' ' || round((e.value ->> 'b')::numeric, 2)::text, ', ' ORDER BY e.key),
           sum(abs(round((e.value ->> 'b')::numeric, 2)))
      INTO v_moved, v_moved_abs
      FROM jsonb_each(t) e
     WHERE e.key <> 'settlement_suspense'
       AND round(COALESCE((e.value ->> 'b')::numeric, 0), 2) <> 0;

    IF v_moved IS NOT NULL THEN
      v_mode := COALESCE(
        (SELECT sm.mode FROM public.ca_ledger_invariant_store_mode sm WHERE sm.store = 'settlement_suspense'),
        (SELECT m.mode FROM public.ca_ledger_invariant_mode m LIMIT 1),
        'refuse');

      IF v_mode = 'refuse' THEN
        /* 20261002135708: recorded first, outside the rollback. */
        BEGIN
          PERFORM public.fn_ca_ledger_refusal_record(jsonb_build_object(
            'kind',          'balance_moved_against_settlement_suspense',
            'account_key',   'settlement_suspense',
            'store',         'settlement_suspense',
            'balance_delta', v_moved_abs,
            'ledger_net',    v_s,
            'mode',          v_mode,
            'moved',         left(v_moved, 2000),
            'first_writer',  left(COALESCE(t -> 'settlement_suspense' ->> 'q', '(unknown statement)'), 1000),
            'message',       format('REFUSED: balance_moved_against_settlement_suspense suspense_legs=%s moved=%s', v_s, left(v_moved, 1500))));
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;
        RAISE EXCEPTION 'REFUSED: balance_moved_against_settlement_suspense suspense_legs=% moved=%',
          v_s, v_moved
          USING ERRCODE = '23514',
                DETAIL  = 'this transaction wrote a chip_ledger leg against settlement_suspense, which holds no balance and is outside the supply count, and moved a covered chip balance; the suspense leg was first written by: '
                          || COALESCE(t -> 'settlement_suspense' ->> 'q', '(unknown statement)'),
                HINT    = 'A door names where its chips come from and go to: app.ledger_counterparty (+ app.ledger_counterparty_entity) before the balance write, or app.ledger_autoskip_<table> and its own leg. An undeclared journal trigger falls to settlement_suspense, and that is what is refused here. A journal-only correction that moves no balance is not affected.';
      END IF;

      INSERT INTO public.ca_ledger_invariant_findings
        (txid, account_key, balance_delta, ledger_net, mode, actor_service, db_role, statement)
      VALUES
        (pg_current_xact_id(), 'settlement_suspense', v_moved_abs, v_s, v_mode,
         current_setting('application_name', true), current_user,
         left(COALESCE(t -> 'settlement_suspense' ->> 'q', left(current_query(), 300)) || ' | moved: ' || v_moved, 1000))
      ON CONFLICT (txid, account_key) DO UPDATE
        SET balance_delta = EXCLUDED.balance_delta,
            ledger_net    = EXCLUDED.ledger_net,
            found_at      = EXCLUDED.found_at,
            statement     = EXCLUDED.statement;
      RAISE WARNING 'OBSERVED: balance_moved_against_settlement_suspense suspense_legs=% moved=% (mode observe; this transaction would be refused)',
        v_s, v_moved;
    END IF;
  END IF;

  PERFORM set_config('ca.ledger_tally_checked', v_ver, true);
  RETURN NULL;
END;
$function$

fn_ca_ledger_tally_add.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_ledger_tally_add(p_key text, p_side text, p_delta numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  t jsonb;
  e jsonb;
  v numeric;
BEGIN
  /* The tally lives in a transaction-local setting, so it is undone with the
     transaction and with any subtransaction (a plpgsql EXCEPTION block) that
     rolls back the write it counted. A SET clause on a function restores only
     the variables it names at exit (measured on production 2026-10-01: a
     set_config(..., true) made inside a SET search_path function was still
     set after it returned), so pinning search_path here does not lose the
     tally. Every object is named by schema regardless. */
  IF p_key IS NULL OR p_delta IS NULL OR round(p_delta, 2) = 0 THEN
    RETURN;
  END IF;
  t := COALESCE(NULLIF(current_setting('ca.ledger_tally', true), '')::jsonb, '{}'::jsonb);
  e := COALESCE(t -> p_key, '{"b":0,"l":0}'::jsonb);
  IF NOT (e ? 'q') THEN
    -- The top-level statement that first touched this account in this
    -- transaction: the name of the door, for the refusal and the finding
    -- (CLAUDE.md 10.86: a refusal names its writer).
    e := e || jsonb_build_object('q', left(COALESCE(current_query(), ''), 300));
  END IF;
  v := round(COALESCE((e ->> p_side)::numeric, 0) + p_delta, 2);
  e := jsonb_set(e, ARRAY[p_side], to_jsonb(v), true);
  t := t || jsonb_build_object(p_key, e);
  PERFORM set_config('ca.ledger_tally', t::text, true);
  PERFORM set_config('ca.ledger_tally_ver',
                     (COALESCE(NULLIF(current_setting('ca.ledger_tally_ver', true), ''), '0')::bigint + 1)::text,
                     true);
END;
$function$

fn_ca_ledger_tally_key.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_ledger_tally_key(p_type text, p_entity uuid, p_club uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_union uuid;
  v_club uuid;
BEGIN
  /* The account a ledger side belongs to, in the covered set, or NULL when the
     side is not a chip store. The conventions are the ones every live writer
     already meets (measured 2026-10-01, seven days, 1,946,078 legs; extended
     2026-10-02 over the same seven days): a player_wallet leg names the user
     and the club; a union leg names the wallet row (fn_ca_autoledger) or the
     union (a declaring payer); a bbj_pool leg names the pool row; a
     table_stack leg names the table; a promo or agent leg names its holder
     (user, club or union); a club wallet or insurance leg names the
     club_wallets row or the club; a spin_reserve leg names the pool (10 of 10
     entities in seven days); a prize or bounty liability leg names the
     tournament (20,169 of 20,169 entities in a day, every one with an escrow
     row); a ticket escrow leg names the ticket, and every issued ticket is one
     float (fn_ca_ticket_escrow_float). */
  CASE p_type
    WHEN 'player_wallet' THEN
      RETURN 'player_wallet:' || COALESCE(p_entity::text, 'null') || ':' || COALESCE(p_club::text, 'null');
    WHEN 'club_treasury' THEN
      RETURN 'club_treasury:' || COALESCE(p_entity::text, 'null');
    WHEN 'table_stack' THEN
      IF p_entity IS NULL OR public.fn_ca_felt_counts_table(p_entity) THEN
        RETURN 'table_stack';
      END IF;
      RETURN NULL;  -- a tournament or Diamond table is not on the cash felt
    WHEN 'union_bank', 'union_wallet' THEN
      SELECT w.union_id INTO v_union FROM public.union_wallets w WHERE w.id = p_entity;
      RETURN p_type || ':' || COALESCE(v_union, p_entity)::text;
    WHEN 'bbj_pool' THEN
      RETURN 'bbj_pool:' || COALESCE(p_entity::text, 'null');
    -- 2026-10-02: every remaining chip store
    WHEN 'agent_wallet' THEN
      RETURN p_type || ':' || COALESCE(p_entity::text, 'null') || ':' || COALESCE(p_club::text, 'null');
    WHEN 'promo_wallet' THEN
      -- Club and union promo banks retain their original global identities.
      -- A user's promo account is scoped to the club that holds its balance.
      IF p_entity IS NULL OR EXISTS(SELECT 1 FROM public.clubs WHERE id=p_entity)
        OR EXISTS(SELECT 1 FROM public.unions WHERE id=p_entity) THEN
        RETURN p_type || ':' || COALESCE(p_entity::text, 'null');
      END IF;
      RETURN p_type || ':' || p_entity::text || ':' || COALESCE(p_club::text, 'null');
    WHEN 'club_wallet', 'insurance_bank' THEN
      SELECT cw.club_id INTO v_club FROM public.club_wallets cw WHERE cw.id = p_entity;
      RETURN p_type || ':' || COALESCE(COALESCE(v_club, p_entity)::text, 'null');
    WHEN 'spin_reserve' THEN
      RETURN 'spin_reserve:' || COALESCE(p_entity::text, 'null');
    WHEN 'prize_liability', 'bounty_liability' THEN
      IF p_entity IS NOT NULL AND NOT public.fn_ca_tournament_counts(p_entity) THEN
        RETURN NULL;  -- a Diamond event's liability is Diamonds in custody
      END IF;
      RETURN 'tournament_liability:' || COALESCE(p_entity::text, 'null');
    WHEN 'escrow' THEN
      RETURN 'ticket_escrow';
    WHEN 'opening_setup', 'leaderboard_round' THEN
      RETURN p_type || ':' || COALESCE(p_entity::text, 'null');
    ELSE
      RETURN NULL;
  END CASE;
END;
$function$

fn_ca_process_hand_post_commit_obligatio.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_process_hand_post_commit_obligations(p_hand_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_table_id uuid;
  v_commit public.hand_atomic_commits%ROWTYPE;
  v_payload jsonb;
  v_hash text;
  v_rake jsonb;
  v_bbj jsonb;
  v_pending jsonb;
  v_item jsonb;
  v_rake_result record;
  v_promo_result jsonb;
  v_pool_id uuid;
  v_union_id uuid;
  v_contribution_id uuid;
  v_insurance_id uuid;
  v_addon_result record;
  v_addon public.table_pending_addons%ROWTYPE;
  v_time_bank_count integer := 0;
  v_promo_count integer := 0;
  v_insurance_count integer := 0;
  v_addon_count integer := 0;
  v_result jsonb;
BEGIN
  /* Read only the scope, then take the per-table mutex before the row lock.
     This gives every hand at one table the same lock order. */
  SELECT c.table_id INTO v_table_id
    FROM public.hand_atomic_commits c
   WHERE c.hand_id = p_hand_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found', 'hand_id', p_hand_id);
  END IF;

  /* 20261019: this tournament's shared lane first, waiting, before any
     lock (re-entered at once when the caller already holds it). */
  PERFORM smarter_private.f06_wait_table_lane(v_table_id);

  PERFORM pg_advisory_xact_lock(
    hashtextextended('hand-post-commit:' || v_table_id::text, 0)
  );

  SELECT c.* INTO v_commit
    FROM public.hand_atomic_commits c
   WHERE c.hand_id = p_hand_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found', 'hand_id', p_hand_id);
  END IF;
  IF v_commit.post_commit_payload IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'legacy_no_obligations',
      'hand_id', p_hand_id
    );
  END IF;
  IF v_commit.post_commit_completed_at IS NOT NULL THEN
    RETURN COALESCE(v_commit.post_commit_result, '{}'::jsonb) || jsonb_build_object(
      'ok', true,
      'already_completed', true,
      'hand_id', p_hand_id,
      'completed_at', v_commit.post_commit_completed_at
    );
  END IF;

  IF EXISTS (
    SELECT 1
      FROM public.hand_atomic_commits earlier
     WHERE earlier.table_id = v_commit.table_id
       AND earlier.hand_number < v_commit.hand_number
       AND earlier.post_commit_payload IS NOT NULL
       AND earlier.post_commit_completed_at IS NULL
  ) THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'predecessor_pending',
      'hand_id', p_hand_id
    );
  END IF;

  v_payload := v_commit.post_commit_payload;
  v_hash := encode(
    extensions.digest(convert_to(v_payload::text, 'UTF8'), 'sha256'),
    'hex'
  );
  IF v_commit.post_commit_payload_hash IS DISTINCT FROM v_hash THEN
    RAISE EXCEPTION 'post-commit obligation payload hash mismatch for hand %', p_hand_id;
  END IF;

  /* Time banks were stamped inside the accepted-hand transaction while the
     exact lease and seat locks were held. A delayed consumer must never apply
     those older values again after hand N+1, a table break, or a seat move. */
  IF jsonb_typeof(v_payload->'time_banks') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'invalid time-bank audit payload for hand %', p_hand_id;
  END IF;
  v_time_bank_count := jsonb_array_length(v_payload->'time_banks');

  IF EXISTS(SELECT 1 FROM public.tables t JOIN public.clubs c ON c.id=t.club_id
      WHERE t.id=v_table_id AND c.asset='diamonds') AND (
    v_payload->'rake' IS DISTINCT FROM 'null'::jsonb
    OR v_payload->'bbj_contribution' IS DISTINCT FROM 'null'::jsonb
    OR v_payload->'pending_addons' IS DISTINCT FROM 'null'::jsonb
    OR v_payload->'promo_playthrough' IS DISTINCT FROM '[]'::jsonb
    OR v_payload->'insurance' IS DISTINCT FROM '[]'::jsonb
  ) THEN
    RAISE EXCEPTION 'diamond_hand_has_chip_obligations';
  END IF;
  v_rake := v_payload->'rake';
  IF v_rake IS NOT NULL AND jsonb_typeof(v_rake) <> 'null' THEN
    IF jsonb_typeof(v_rake) <> 'object'
       OR COALESCE((v_rake->>'amount')::numeric, 0) <= 0
       OR (v_rake->>'club_id') !~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'invalid rake obligation for hand %', p_hand_id;
    END IF;
    IF v_commit.hand_number > 2147483647 THEN
      RAISE EXCEPTION 'rake hand number exceeds downstream integer contract: %',
        v_commit.hand_number;
    END IF;

    SELECT * INTO v_rake_result
      FROM public.atomic_distribute_rake(
        v_commit.table_id,
        (v_rake->>'club_id')::uuid,
        v_commit.hand_id,
        v_commit.hand_number::integer,
        (v_rake->>'amount')::numeric,
        COALESCE((v_rake->>'bbj')::numeric, 0),
        NULLIF(v_rake->>'pot', '')::numeric,
        NULLIF(v_rake->>'num_players', '')::integer,
        COALESCE(v_rake->'contributions', '{}'::jsonb),
        NULLIF(v_rake->>'tournament_id', '')::uuid,
        COALESCE(v_rake->'returned_uncalled', '{}'::jsonb),
        COALESCE(NULLIF(v_rake->>'method', ''), 'WEIGHTED_CONTRIBUTED')
      );
    IF NOT FOUND OR NOT (
      COALESCE(v_rake_result.applied, false)
      OR COALESCE(v_rake_result.already_processed, false)
      OR v_rake_result.rake_record_id IS NOT NULL
    ) THEN
      RAISE EXCEPTION 'rake obligation did not produce a receipt for hand %', p_hand_id;
    END IF;
  END IF;

  v_bbj := v_payload->'bbj_contribution';
  IF v_bbj IS NOT NULL AND jsonb_typeof(v_bbj) <> 'null' THEN
    IF jsonb_typeof(v_bbj) <> 'object'
       OR COALESCE((v_bbj->>'amount')::numeric, 0) <= 0
       OR (v_bbj->>'club_id') !~*
          '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'invalid BBJ contribution obligation for hand %', p_hand_id;
    END IF;

    SELECT c.union_id INTO v_union_id
      FROM public.clubs c
     WHERE c.id = (v_bbj->>'club_id')::uuid;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'BBJ obligation club not found for hand %', p_hand_id;
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended(
      'bbj-pool:' || COALESCE(v_union_id::text, 'club:' || (v_bbj->>'club_id')),
      0
    ));
    IF v_union_id IS NULL THEN
      SELECT p.id INTO v_pool_id
        FROM public.bbj_pools p
       WHERE p.club_id = (v_bbj->>'club_id')::uuid
         AND p.status = 'active'
       ORDER BY p.created_at, p.id
       LIMIT 1
       FOR UPDATE;
    ELSE
      SELECT p.id INTO v_pool_id
        FROM public.bbj_pools p
       WHERE p.union_id = v_union_id
         AND p.status = 'active'
       ORDER BY p.created_at, p.id
       LIMIT 1
       FOR UPDATE;
    END IF;

    IF v_pool_id IS NULL THEN
      IF v_union_id IS NULL THEN
        INSERT INTO public.bbj_pools(
          club_id, main_balance, backup_balance, promo_balance, status
        ) VALUES (
          (v_bbj->>'club_id')::uuid, 0, 0, 0, 'active'
        ) RETURNING id INTO v_pool_id;
      ELSE
        INSERT INTO public.bbj_pools(
          union_id, main_balance, backup_balance, promo_balance, status
        ) VALUES (
          v_union_id, 0, 0, 0, 'active'
        ) RETURNING id INTO v_pool_id;
      END IF;
    END IF;

    SELECT r.id INTO v_contribution_id
      FROM public.bbj_record_contribution(
        v_pool_id,
        v_commit.hand_id,
        v_commit.table_id,
        (v_bbj->>'amount')::numeric,
        0, 0, 0,
        COALESCE((v_bbj->>'big_blind')::numeric, 2),
        v_commit.hand_number::integer,
        (v_bbj->>'club_id')::uuid
      ) r;
    IF v_contribution_id IS NULL THEN
      RAISE EXCEPTION 'BBJ contribution produced no receipt for hand %', p_hand_id;
    END IF;
  END IF;

  FOR v_item IN
    SELECT value
      FROM jsonb_array_elements(v_payload->'promo_playthrough')
     ORDER BY value->>'user_id'
  LOOP
    IF (v_item->>'club_id') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR (v_item->>'user_id') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR COALESCE((v_item->>'wagered')::numeric, 0) <= 0 THEN
      RAISE EXCEPTION 'invalid promo obligation for hand %', p_hand_id;
    END IF;
    v_promo_result := public.promo_apply_playthrough(
      (v_item->>'club_id')::uuid,
      (v_item->>'user_id')::uuid,
      (v_item->>'wagered')::numeric
    );
    IF v_promo_result->>'reason' IN ('engine_only', 'no_wager') THEN
      RAISE EXCEPTION 'promo obligation refused for hand %: %',
        p_hand_id, v_promo_result;
    END IF;
    v_promo_count := v_promo_count + 1;
  END LOOP;

  FOR v_item IN
    SELECT value
      FROM jsonb_array_elements(v_payload->'insurance')
     ORDER BY value->>'player_id', value->>'kind'
  LOOP
    IF (v_item->>'club_id') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
       OR (v_item->>'player_id') !~*
         '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'invalid insurance obligation for hand %', p_hand_id;
    END IF;
    SELECT r.id INTO v_insurance_id
      FROM public.record_insurance_transaction(
        v_commit.table_id,
        (v_item->>'club_id')::uuid,
        v_commit.hand_number::integer,
        (v_item->>'player_id')::uuid,
        COALESCE((v_item->>'equity_percent')::numeric, 0),
        COALESCE((v_item->>'premium')::numeric, 0),
        COALESCE((v_item->>'insured_amount')::numeric, 0),
        COALESCE((v_item->>'payout')::numeric, 0),
        COALESCE((v_item->>'player_won')::boolean, false),
        COALESCE(NULLIF(v_item->>'kind', ''), 'insurance')::varchar
      ) r;
    IF v_insurance_id IS NULL THEN
      RAISE EXCEPTION 'insurance obligation produced no receipt for hand %', p_hand_id;
    END IF;
    v_insurance_count := v_insurance_count + 1;
  END LOOP;

  v_pending := v_payload->'pending_addons';
  IF v_pending IS NOT NULL AND jsonb_typeof(v_pending) <> 'null' THEN
    IF jsonb_typeof(v_pending) <> 'object'
       OR COALESCE((v_pending->>'enabled')::boolean, false) IS NOT TRUE
       OR jsonb_typeof(v_pending->'ids') IS DISTINCT FROM 'array'
       /* 20261105: a JSON null max_buy_in is uncapped (fixed-limit tables);
          resolve_pending_addon reads NULL the same way. A non-number or a
          number <= 0 is still refused. */
       OR COALESCE(jsonb_typeof(v_pending->'max_buy_in'), 'missing') NOT IN ('number', 'null')
       OR (jsonb_typeof(v_pending->'max_buy_in') = 'number'
           AND (v_pending->>'max_buy_in')::numeric <= 0) THEN
      RAISE EXCEPTION 'invalid pending-add-on obligation for hand %', p_hand_id;
    END IF;
    FOR v_item IN
      SELECT value
        FROM jsonb_array_elements(v_pending->'ids')
       ORDER BY value #>> '{}'
    LOOP
      IF (v_item #>> '{}') !~*
           '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      THEN
        RAISE EXCEPTION 'pending add-on % is not frozen for table % (hand %)',
          v_item, v_commit.table_id, p_hand_id;
      END IF;
      -- Recovery can encounter an ID also frozen by an earlier accepted
      -- hand. The resolver owns exactly-once delivery and returns its stored
      -- result on replay. A resolved row is evidence, not a failed payment.
      SELECT a.* INTO v_addon
        FROM public.table_pending_addons a
       WHERE a.id = (v_item #>> '{}')::uuid
         AND a.table_id = v_commit.table_id
       FOR UPDATE;
      IF NOT FOUND THEN
        RAISE EXCEPTION 'pending add-on % does not belong to table % (hand %)',
          v_item, v_commit.table_id, p_hand_id;
      END IF;
      SELECT * INTO v_addon_result
        FROM public.resolve_pending_addon(
          (v_item #>> '{}')::uuid,
          NULLIF(v_pending->>'max_buy_in', '')::numeric
        );
      IF NOT FOUND THEN
        RAISE EXCEPTION 'pending add-on % produced no receipt for hand %',
          v_item, p_hand_id;
      END IF;
      IF v_addon.amount IS NULL OR v_addon.amount <= 0
         OR v_addon.amount::text IN ('NaN', 'Infinity', '-Infinity')
         OR (v_addon.resolved_at IS NOT NULL AND
             (v_addon.applied_to_stack IS NULL OR v_addon.refunded IS NULL))
         OR v_addon_result.applied IS NULL OR v_addon_result.applied < 0
         OR v_addon_result.applied::text IN ('NaN', 'Infinity', '-Infinity')
         OR v_addon_result.applied <> round(v_addon_result.applied, 2)
         OR v_addon_result.refunded IS NULL OR v_addon_result.refunded < 0
         OR v_addon_result.refunded::text IN ('NaN', 'Infinity', '-Infinity')
         OR v_addon_result.refunded <> round(v_addon_result.refunded, 2)
         OR v_addon_result.applied + v_addon_result.refunded
              IS DISTINCT FROM round(v_addon.amount, 2)
      THEN
        RAISE EXCEPTION 'pending add-on % has an incomplete resolution receipt for hand %',
          v_item, p_hand_id;
      END IF;
      v_addon_count := v_addon_count + 1;
    END LOOP;
  END IF;

  v_result := jsonb_build_object(
    'ok', true,
    'already_completed', false,
    'hand_id', p_hand_id,
    'hand_number', v_commit.hand_number,
    'time_banks', v_time_bank_count,
    'rake', v_rake IS NOT NULL AND jsonb_typeof(v_rake) <> 'null',
    'bbj_contribution', v_bbj IS NOT NULL AND jsonb_typeof(v_bbj) <> 'null',
    'promo_playthrough', v_promo_count,
    'insurance', v_insurance_count,
    'pending_addons', v_addon_count
  );

  UPDATE public.hand_atomic_commits c
     SET post_commit_completed_at = clock_timestamp(),
         post_commit_result = v_result
   WHERE c.hand_id = p_hand_id
     AND c.post_commit_completed_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'post-commit completion receipt was lost for hand %', p_hand_id;
  END IF;

  -- The original pending-application event owns final accounting admission
  -- too. All applications and the immutable completion receipt above are
  -- visible now; no later repair loop or money replay supplies this proof.
  IF v_addon_count>0 AND EXISTS(SELECT 1 FROM public.union_pnl_cash_outcomes o
    WHERE o.table_id=v_commit.table_id AND o.hand_number=v_commit.hand_number
      AND o.evidence->>'status'='blocked') THEN
    DECLARE escrow_proof jsonb;escrow_original jsonb;
    BEGIN
      IF smarter_private.original_inventory_proof_sources_match() IS DISTINCT FROM true THEN
        escrow_proof:=jsonb_build_object('status','refused','reason','original_sources_unqualified');
      ELSIF public.fn_platform_frozen() IS DISTINCT FROM false THEN
        escrow_proof:=jsonb_build_object('status','refused','reason','accounting_admission_platform_frozen');
      ELSE
        escrow_proof:=public.fn_union_pnl_prove_posthand_escrow(v_commit.table_id,v_commit.hand_number);
      END IF;
      IF escrow_proof->>'status'='proven' THEN
        escrow_original:=smarter_private.posthand_escrow_original_snapshot(v_commit.table_id,v_commit.hand_number);
        PERFORM public.fn_union_pnl_certify_posthand_escrow(v_commit.table_id,v_commit.hand_number,
          md5((escrow_original->'proof')::text),
          encode(extensions.digest(convert_to(escrow_original::text,'UTF8'),'sha256'),'hex'));
      ELSIF escrow_proof->>'status'='refused' THEN
        -- Accounting qualification cannot hold otherwise valid payments.
        -- This is still the original transaction's unpublished completion
        -- receipt, not a rewrite of any already committed financial record.
        v_result:=v_result||jsonb_build_object('accounting_admission',escrow_proof);
        UPDATE public.hand_atomic_commits c SET post_commit_result=v_result
         WHERE c.hand_id=p_hand_id AND c.post_commit_completed_at IS NOT NULL;
        IF NOT FOUND THEN RAISE EXCEPTION 'posthand_escrow_refusal_receipt_lost';END IF;
      ELSE
        RAISE EXCEPTION 'posthand_escrow_original_proof_unknown';
      END IF;
    END;
  END IF;

  RETURN v_result;
END;
$function$

fn_ca_tally_balance_move.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_tally_balance_move()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  o jsonb := CASE WHEN TG_OP = 'INSERT' THEN NULL ELSE to_jsonb(OLD) END;
  n jsonb := CASE WHEN TG_OP = 'DELETE' THEN NULL ELSE to_jsonb(NEW) END;
  k_old text; k_new text;
  v_old numeric := 0; v_new numeric := 0;
BEGIN
  CASE TG_TABLE_NAME
    WHEN 'club_members' THEN
      IF o IS NOT NULL THEN
        k_old := 'player_wallet:' || COALESCE(o ->> 'user_id', 'null') || ':' || COALESCE(o ->> 'club_id', 'null');
        v_old := COALESCE((o ->> 'chip_balance')::numeric, 0);
      END IF;
      IF n IS NOT NULL THEN
        k_new := 'player_wallet:' || COALESCE(n ->> 'user_id', 'null') || ':' || COALESCE(n ->> 'club_id', 'null');
        v_new := COALESCE((n ->> 'chip_balance')::numeric, 0);
      END IF;
    WHEN 'clubs' THEN
      IF o IS NOT NULL THEN
        k_old := 'club_treasury:' || (o ->> 'id');
        v_old := COALESCE((o ->> 'chip_treasury')::numeric, 0) + COALESCE((o ->> 'chip_pool')::numeric, 0);
      END IF;
      IF n IS NOT NULL THEN
        k_new := 'club_treasury:' || (n ->> 'id');
        v_new := COALESCE((n ->> 'chip_treasury')::numeric, 0) + COALESCE((n ->> 'chip_pool')::numeric, 0);
      END IF;
    WHEN 'table_seats' THEN
      /* A seat is on the felt while it is occupied (left_at IS NULL) and its
         table is a cash chip table. A vacated seat's stack has left the felt
         whether or not the row zeroes it, which is exactly what
         fn_log_seat_stack_exit records and what a cash-out leg explains. */
      k_old := 'table_stack'; k_new := 'table_stack';
      IF o IS NOT NULL AND (o ->> 'left_at') IS NULL
         AND public.fn_ca_felt_counts_table((o ->> 'table_id')::uuid) THEN
        v_old := COALESCE((o ->> 'stack')::numeric, 0);
      END IF;
      IF n IS NOT NULL AND (n ->> 'left_at') IS NULL
         AND public.fn_ca_felt_counts_table((n ->> 'table_id')::uuid) THEN
        v_new := COALESCE((n ->> 'stack')::numeric, 0);
      END IF;
    WHEN 'table_pending_addons' THEN
      /* The add-on's leg lands at request time; the chips wait here until the
         hand ends. They are on the felt the whole time (fn_ca_supply_snapshot
         pending_addons, 2026-09-12), so resolving one is not a movement. */
      k_old := 'table_stack'; k_new := 'table_stack';
      IF o IS NOT NULL AND (o ->> 'resolved_at') IS NULL
         AND public.fn_ca_felt_counts_table((o ->> 'table_id')::uuid) THEN
        v_old := COALESCE((o ->> 'amount')::numeric, 0);
      END IF;
      IF n IS NOT NULL AND (n ->> 'resolved_at') IS NULL
         AND public.fn_ca_felt_counts_table((n ->> 'table_id')::uuid) THEN
        v_new := COALESCE((n ->> 'amount')::numeric, 0);
      END IF;
    WHEN 'hand_atomic_commits' THEN
      /* THE FEES A HAND TAKES OFF ITS SEATS STAY ON THE FELT UNTIL THEIR LEGS
         ARE POSTED (20261001231409). The accepted-hand transaction moves the
         seats by inflow - rake - bbj and writes no leg for the fees. Their
         legs - table_stack -> union_wallet or chip_retirement for the rake,
         table_stack -> bbj_pool for the drop, the insurance bank's leg for the
         inflow - are posted by fn_ca_process_hand_post_commit_obligations in
         a LATER transaction, under the club wallet, VIP carry and pool locks
         the commit path must not wait on. So the hand's own receipt carries
         the fees as felt from the moment its envelope is stored until the
         moment that envelope completes - in the same transaction that posts
         the legs. Each transaction balances on its own, and a hand whose
         second half has not run yet reads as fees still on the felt, never as
         chips that vanished. Scoped exactly like the seat: the cash chip felt. */
      k_old := 'table_stack'; k_new := 'table_stack';
      IF o IS NOT NULL AND (o ->> 'post_commit_payload') IS NOT NULL
         AND (o ->> 'post_commit_completed_at') IS NULL
         AND public.fn_ca_felt_counts_table((o ->> 'table_id')::uuid) THEN
        v_old := COALESCE((o -> 'stack_result' ->> 'rake')::numeric, 0)
               + COALESCE((o -> 'stack_result' ->> 'bbj')::numeric, 0)
               - COALESCE((o -> 'stack_result' ->> 'inflow')::numeric, 0);
      END IF;
      IF n IS NOT NULL AND (n ->> 'post_commit_payload') IS NOT NULL
         AND (n ->> 'post_commit_completed_at') IS NULL
         AND public.fn_ca_felt_counts_table((n ->> 'table_id')::uuid) THEN
        v_new := COALESCE((n -> 'stack_result' ->> 'rake')::numeric, 0)
               + COALESCE((n -> 'stack_result' ->> 'bbj')::numeric, 0)
               - COALESCE((n -> 'stack_result' ->> 'inflow')::numeric, 0);
      END IF;
    WHEN 'union_wallets' THEN
      /* Two accounts on one row: the bank (chip_balance) and the five
         operating wallets, both keyed by the union. */
      IF o IS NOT NULL THEN
        PERFORM public.fn_ca_ledger_tally_add('union_bank:' || (o ->> 'union_id'), 'b',
                  -COALESCE((o ->> 'chip_balance')::numeric, 0));
        k_old := 'union_wallet:' || (o ->> 'union_id');
        v_old := COALESCE((o ->> 'rake_wallet')::numeric, 0) + COALESCE((o ->> 'bbj_wallet')::numeric, 0)
               + COALESCE((o ->> 'promo_wallet')::numeric, 0) + COALESCE((o ->> 'insurance_wallet')::numeric, 0)
               + COALESCE((o ->> 'spin_reserve_wallet')::numeric, 0);
      END IF;
      IF n IS NOT NULL THEN
        PERFORM public.fn_ca_ledger_tally_add('union_bank:' || (n ->> 'union_id'), 'b',
                  COALESCE((n ->> 'chip_balance')::numeric, 0));
        k_new := 'union_wallet:' || (n ->> 'union_id');
        v_new := COALESCE((n ->> 'rake_wallet')::numeric, 0) + COALESCE((n ->> 'bbj_wallet')::numeric, 0)
               + COALESCE((n ->> 'promo_wallet')::numeric, 0) + COALESCE((n ->> 'insurance_wallet')::numeric, 0)
               + COALESCE((n ->> 'spin_reserve_wallet')::numeric, 0);
      END IF;
    WHEN 'bbj_pools' THEN
      IF o IS NOT NULL THEN
        k_old := 'bbj_pool:' || (o ->> 'id');
        v_old := COALESCE((o ->> 'main_balance')::numeric, 0) + COALESCE((o ->> 'backup_balance')::numeric, 0)
               + COALESCE((o ->> 'promo_balance')::numeric, 0);
      END IF;
      IF n IS NOT NULL THEN
        k_new := 'bbj_pool:' || (n ->> 'id');
        v_new := COALESCE((n ->> 'main_balance')::numeric, 0) + COALESCE((n ->> 'backup_balance')::numeric, 0)
               + COALESCE((n ->> 'promo_balance')::numeric, 0);
      END IF;
    ELSE
      RAISE EXCEPTION 'fn_ca_tally_balance_move is not configured for %', TG_TABLE_NAME;
  END CASE;

  /* A row that changes account (a seat changing table, a membership changing
     club) leaves one account and arrives in another; both sides are counted. */
  IF k_old IS NOT NULL AND k_new IS NOT NULL AND k_old = k_new THEN
    PERFORM public.fn_ca_ledger_tally_add(k_new, 'b', v_new - v_old);
  ELSE
    IF k_old IS NOT NULL THEN PERFORM public.fn_ca_ledger_tally_add(k_old, 'b', -v_old); END IF;
    IF k_new IS NOT NULL THEN PERFORM public.fn_ca_ledger_tally_add(k_new, 'b', v_new); END IF;
  END IF;
  RETURN NULL;
END;
$function$

fn_ca_tally_ledger_leg.definition:
CREATE OR REPLACE FUNCTION public.fn_ca_tally_ledger_leg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  /* SETTLEMENT SUSPENSE IS NOT A COUNTERPARTY FOR A BALANCE (2026-10-02).
     Every leg with settlement_suspense on either side is counted, before the
     journal-only exemption below, under a key no store resolves to. The
     commit check refuses a transaction that wrote one and moved any covered
     balance; a journal-only correction moves none and still commits. */
  IF NEW.from_type = 'settlement_suspense' OR NEW.to_type = 'settlement_suspense' THEN
    PERFORM public.fn_ca_ledger_tally_add('settlement_suspense', 's', abs(NEW.amount));
  END IF;
  /* A journal-only restatement (CLAUDE.md 10.9 rule 3, fn_ca_post_correction)
     moves no balance by design and is outside every meter, including this one. */
  IF NEW.category = 'correction' AND NEW.metadata ->> 'posted_via' = 'fn_ca_post_correction' THEN
    RETURN NULL;
  END IF;
  PERFORM public.fn_ca_ledger_tally_add(
    CASE WHEN NEW.to_type = 'escrow' AND NEW.category IN ('escrow_hold', 'escrow_release')
      THEN 'cashout_escrow:' || COALESCE(NEW.to_entity_id::text, 'null')
      ELSE public.fn_ca_ledger_tally_key(NEW.to_type, NEW.to_entity_id, NEW.club_id) END, 'l', NEW.amount);
  PERFORM public.fn_ca_ledger_tally_add(
    CASE WHEN NEW.from_type = 'escrow' AND NEW.category IN ('escrow_hold', 'escrow_release')
      THEN 'cashout_escrow:' || COALESCE(NEW.from_entity_id::text, 'null')
      ELSE public.fn_ca_ledger_tally_key(NEW.from_type, NEW.from_entity_id, NEW.club_id) END, 'l', -NEW.amount);
  RETURN NULL;
END;
$function$

fn_lock_cash_bank_accounting_week.definition:
CREATE OR REPLACE FUNCTION public.fn_lock_cash_bank_accounting_week(p_club_id uuid, p_game_union_id uuid, p_banked_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE coordinator uuid;memberships int;week_from timestamptz;week_to timestamptz;
BEGIN
 IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 IF p_club_id IS NULL OR p_banked_at IS DISTINCT FROM transaction_timestamp() THEN
  RAISE EXCEPTION 'cash_bank_week_identity_invalid' USING ERRCODE='22023'; END IF;
 coordinator:=p_game_union_id;
 IF coordinator IS NULL THEN
  -- A private game's bank remains local. Its weekly coordinator is determined
  -- independently from the observed membership, matching the source contract.
  SELECT count(*),(array_agg((h.after_terms->>'union_id')::uuid))[1] INTO memberships,coordinator FROM (
   SELECT DISTINCT ON(entity_key) entity_key,after_terms FROM public.accounting_agreement_history
    WHERE entity_type='union_clubs' AND club_id=p_club_id AND observed_at<=p_banked_at
    ORDER BY entity_key,observed_at DESC,id DESC
  )h WHERE h.after_terms IS NOT NULL AND h.after_terms->>'club_id'=p_club_id::text;
  IF memberships>1 THEN RAISE EXCEPTION 'cash_bank_coordinator_ambiguous' USING ERRCODE='55000'; END IF;
 END IF;
 week_from:=public.fn_union_week_start(p_banked_at);week_to:=public.fn_union_week_start(week_from+interval '8 days');
 -- Shared: this guard only READS the closed-week tables. It excludes the
 -- weekly close, never a sibling bank.
 PERFORM pg_advisory_xact_lock_shared(hashtextextended(
  CASE WHEN coordinator IS NOT NULL THEN 'union-accounting:' ELSE 'club-accounting:' END
  ||COALESCE(coordinator,p_club_id)::text||':'||extract(epoch FROM week_from)::text||':'||extract(epoch FROM week_to)::text,0));
 IF EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r WHERE r.period_start=week_from AND r.period_end=week_to
   AND ((coordinator IS NOT NULL AND r.union_id=coordinator) OR (coordinator IS NULL AND r.standalone_club_id=p_club_id)))
  OR EXISTS(SELECT 1 FROM public.union_rakeback_log l WHERE l.union_id=coordinator AND l.period_start<=p_banked_at AND l.period_end>p_banked_at)
 THEN RAISE EXCEPTION 'cash_bank_closed_week_requires_adjustment' USING ERRCODE='55000'; END IF;
END $function$

fn_project_hand_side_effects.definition:
CREATE OR REPLACE FUNCTION public.fn_project_hand_side_effects(p_hand_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_table_id uuid;
  v_hand_number bigint;
  v_history_table_id uuid;
  v_history_hand_number bigint;
  v_commit_table_id uuid;
  v_commit_hand_number bigint;
  v_post_commit jsonb;
  v_seat_uid uuid;
BEGIN
  IF NOT (current_user IN ('postgres','service_role')) THEN
    RAISE EXCEPTION 'fn_project_hand_side_effects is engine/service only';
  END IF;

  /* LOCK ORDER 1: read the exact durable scope without claiming the outbox.
     Another worker may finish it after this read; the implementation claim
     below remains the sole authority to apply projections. */
  SELECT o.table_id, o.hand_number
    INTO v_table_id, v_hand_number
    FROM public.hand_projection_outbox o
   WHERE o.hand_id = p_hand_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'not_pending',
      'hand_id', p_hand_id
    );
  END IF;

  SELECT h.table_id, h.hand_number
    INTO v_history_table_id, v_history_hand_number
    FROM public.hand_history h
   WHERE h.id = p_hand_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'pending hand projection has no hand history row: %', p_hand_id;
  END IF;

  SELECT c.table_id, c.hand_number
    INTO v_commit_table_id, v_commit_hand_number
    FROM public.hand_atomic_commits c
   WHERE c.hand_id = p_hand_id;
  IF NOT FOUND
     OR v_history_table_id IS DISTINCT FROM v_table_id
     OR v_history_hand_number IS DISTINCT FROM v_hand_number
     OR v_commit_table_id IS DISTINCT FROM v_table_id
     OR v_commit_hand_number IS DISTINCT FROM v_hand_number THEN
    RAISE EXCEPTION
      'pending hand projection scope disagrees with immutable hand receipt: %',
      p_hand_id;
  END IF;

  /* LOCK ORDER 1b (20261019): this tournament's shared lane, waiting, before
     any lock, so the post-commit and projection writes below are never
     refused by a tournament authority mid-transaction. */
  PERFORM smarter_private.f06_wait_table_lane(v_table_id);

  /* LOCK ORDER 2: every path that can consume the frozen post-commit envelope
     owns this per-table advisory lock before reaching any player/stat row. */
  PERFORM pg_advisory_xact_lock(
    hashtextextended('hand-post-commit:' || v_table_id::text, 0)
  );

  /* LOCK ORDER 3: consume the exact stored envelope, or leave the outbox row
     untouched. predecessor_pending is returned unchanged so the event-driven
     worker preserves causal order. Any thrown validation/hash error aborts the
     transaction and is intentionally not converted into success. */
  /* LOCK ORDER 2b (20261015094418): one player order for the whole
     transaction. The rake, promo and projection passes below each touch a
     player's player_stats row, each in its own order; two hands sharing
     players deadlocked between passes. Every seated player is claimed here,
     in uuid order, before any pass runs. */
  FOR v_seat_uid IN
    SELECT DISTINCT (pl->>'userId')::uuid
      FROM public.hand_history h,
           jsonb_array_elements(CASE WHEN jsonb_typeof(h.players) = 'array'
                                     THEN h.players ELSE '[]'::jsonb END) pl
     WHERE h.id = p_hand_id
       AND (pl->>'userId') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
     ORDER BY 1
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended('player-stats:' || v_seat_uid::text, 0));
  END LOOP;

  v_post_commit :=
    public.fn_ca_process_hand_post_commit_obligations(p_hand_id);
  IF COALESCE((v_post_commit->>'ok')::boolean, false) IS NOT TRUE
     AND COALESCE(v_post_commit->>'reason', '') <> 'legacy_no_obligations' THEN
    RETURN COALESCE(v_post_commit, '{}'::jsonb) || jsonb_build_object(
      'projection_applied', false,
      'hand_id', p_hand_id
    );
  END IF;

  /* A newly completed envelope still holds the union wallet row until this
     transaction commits. End this pass before taking projection locks or
     writing dashboard facts. The outbox row is the durable continuation.
     The existing worker already defers predecessor_pending without claiming
     success: here its predecessor is the just-completed financial phase. */
  IF (v_post_commit->>'ok')::boolean IS TRUE
     AND (v_post_commit->>'already_completed')::boolean IS FALSE THEN
    RETURN jsonb_build_object(
      'ok', false,
      'reason', 'predecessor_pending',
      'detail', 'post_commit_completed_in_this_transaction',
      'projection_applied', false,
      'hand_id', p_hand_id
    );
  END IF;

  /* LOCK ORDER 4: projection serialisation comes after post-commit. The
     preserved implementation next claims this exact outbox row FOR UPDATE,
     checks projection predecessors, applies the unchanged projections, and
     deletes through a0_finish_hand_post_commit_obligations. The trigger's
     second processor call is an idempotent completed/legacy assertion while
     this transaction still owns both advisory locks. */
  PERFORM pg_advisory_xact_lock(
    hashtextextended('hand-projection:' || v_table_id::text, 0)
  );

  RETURN public.fn_project_hand_side_effects_after_post_commit_20260908(
    p_hand_id
  );
END;
$function$

trg_finish_hand_post_commit_obligations.definition:
CREATE OR REPLACE FUNCTION public.trg_finish_hand_post_commit_obligations()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_result jsonb;
BEGIN
  v_result := public.fn_ca_process_hand_post_commit_obligations(OLD.hand_id);
  IF COALESCE((v_result->>'ok')::boolean, false) IS NOT TRUE
     AND v_result->>'reason' <> 'legacy_no_obligations' THEN
    RAISE EXCEPTION 'hand post-commit obligations remain pending for %: %',
      OLD.hand_id, v_result;
  END IF;
  RETURN OLD;
END;
$function$
